// ─── LOGO HELPER ────────────────────────────────────────────────────────────
// Uses Google's favicon service — works for every website, no API key needed
export function getLogo(url) {
  try {
    const domain = new URL(url).hostname;
    return `https://www.google.com/s2/favicons?domain=${domain}&sz=64`;
  } catch {
    return null;
  }
}

